function methodsHtml(){methodRecords=D.getMethodRecords();return`<div class="card settings-card-prod methods-settings-v13"><h2>وسائل الدفع</h2><p>الوسائل الموقوفة تختفي من العمليات الجديدة وتبقى محفوظة في التاريخ القديم.</p><div class="methods-list-v13">${methodRecords.map(item=>`<div class="method-row-v13"><div><b>${esc(item.name)}</b><small>${item.active?'مفعلة':'موقوفة'}</small></div><div><button class="mini edit-method-v13" data-id="${esc(item.id)}">تعديل</button><button class="mini toggle-method-v13" data-id="${esc(item.id)}">${item.active?'إيقاف':'تفعيل'}</button></div></div>`).join('')}</div><button class="button" id="addMethodV13">＋ إضافة وسيلة دفع</button></div>`;}
function enhanceFinanceSettings(force=false){if(location.hash!=='#settings')return;const grid=document.querySelector('.settings-grid-prod');if(!grid)return;if(force)grid.querySelector('.methods-settings-v13')?.remove();if(!grid.querySelector('.methods-settings-v13'))grid.insertAdjacentHTML('beforeend',methodsHtml());const addMethod=document.getElementById('addMethodV13');if(addMethod)addMethod.onclick=()=>methodEditor();document.querySelectorAll('.edit-method-v13').forEach(button=>button.onclick=()=>methodEditor(button.dataset.id));document.querySelectorAll('.toggle-method-v13').forEach(button=>button.onclick=()=>{methodRecords=D.getMethodRecords();const item=methodRecords.find(value=>value.id===button.dataset.id);if(!item)return;if(item.active&&methodRecords.filter(value=>value.active).length<=1)return alert('يجب أن تبقى وسيلة دفع واحدة مفعلة على الأقل.');item.active=!item.active;D.saveMethodRecords(methodRecords);enhanceFinanceSettings(true);});window.EFC_AUTOCOMPLETE_OFF_V13?.(grid);}

